window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["cohere"]={html:"<div class=\"own-cohere\">\n  <!-- ── ANNOUNCEMENT ────────────────────────────────────────────────────── -->\n  <div class=\"co-announce\" id=\"coAnnounce\">\n    <p>Northwind Command is now generally available for regulated operations teams. <a href=\"#\">Read the launch note</a></p>\n    <button class=\"co-announce-x\" type=\"button\" id=\"coAnnounceX\" aria-label=\"Dismiss announcement\">&times;</button>\n  </div>\n\n  <!-- ── NAV (logo left · menu centred · actions right) ──────────────────── -->\n  <header class=\"co-nav\" id=\"coNav\">\n    <a class=\"co-wordmark\" href=\"#co-top\" aria-label=\"Northwind home\">Northwind</a>\n    <nav class=\"co-menu\" aria-label=\"Primary\">\n      <a href=\"#co-product\">Product</a>\n      <a href=\"#co-proof\">Customers</a>\n      <a href=\"#co-editorial\">Research</a>\n      <a href=\"#co-plans\">Pricing</a>\n      <a href=\"#co-foot\">Company</a>\n    </nav>\n    <div class=\"co-nav-right\">\n      <a class=\"co-nav-link\" href=\"#\">Sign in</a>\n      <a class=\"co-btn co-btn-primary co-btn-sm\" href=\"#co-plans\">Request a demo</a>\n      <button class=\"co-burger\" type=\"button\" id=\"coBurger\" aria-label=\"Open menu\" aria-expanded=\"false\"><span></span><span></span></button>\n    </div>\n  </header>\n\n  <main id=\"co-top\">\n    <!-- ── HERO ───────────────────────────────────────────────────────────── -->\n    <section class=\"co-hero\" aria-labelledby=\"coHeroH\">\n      <p class=\"co-eyebrow\">Operations intelligence</p>\n      <h1 id=\"coHeroH\" class=\"co-hero-title\">The operations layer<br>for serious teams</h1>\n      <p class=\"co-hero-sub\">Northwind turns scattered dashboards into one governed surface — every region, line, and shift reconciled into a single source operations can act on.</p>\n      <div class=\"co-hero-cta\">\n        <a class=\"co-btn co-btn-primary\" href=\"#co-plans\">Request a demo</a>\n        <a class=\"co-link\" href=\"#co-product\">Explore the platform <span aria-hidden=\"true\">&rarr;</span></a>\n      </div>\n\n      <div class=\"co-hero-media\">\n        <article class=\"co-media-card co-media-wide\" aria-label=\"Northwind Command console\">\n          <div class=\"co-console\">\n            <div class=\"co-console-bar\">\n              <span class=\"co-console-name\">Northwind Command</span>\n              <span class=\"co-chip co-chip-live\"><i aria-hidden=\"true\"></i>Live</span>\n            </div>\n            <div class=\"co-console-body\">\n              <div class=\"co-prompt\">\n                <span class=\"co-prompt-dot\" aria-hidden=\"true\"></span>\n                <span class=\"co-prompt-txt\" id=\"coPrompt\">Reconcile line yield across all regions for week 41</span>\n              </div>\n              <div class=\"co-console-cols\">\n                <div class=\"co-console-col\">\n                  <span class=\"co-console-h\">Agents</span>\n                  <span class=\"co-agent\"><i class=\"co-agent-dot co-a1\" aria-hidden=\"true\"></i>Reconciler</span>\n                  <span class=\"co-agent\"><i class=\"co-agent-dot co-a2\" aria-hidden=\"true\"></i>Anomaly scout</span>\n                  <span class=\"co-agent\"><i class=\"co-agent-dot co-a3\" aria-hidden=\"true\"></i>Digest writer</span>\n                </div>\n                <div class=\"co-console-col co-console-answer\">\n                  <span class=\"co-console-h\">Response</span>\n                  <p>Week 41 yield is 94.6% across 14 lines &mdash; 3 lines below target, all in Busan.</p>\n                  <div class=\"co-badges\">\n                    <span class=\"co-badge\">Dataverse</span>\n                    <span class=\"co-badge\">Snowflake</span>\n                    <span class=\"co-badge\">SAP</span>\n                  </div>\n                </div>\n              </div>\n              <div class=\"co-console-foot\">\n                <span class=\"co-chip\">12 agents online</span>\n                <span class=\"co-chip\">2.4k sources connected</span>\n              </div>\n            </div>\n          </div>\n        </article>\n\n        <article class=\"co-media-card co-media-photo\" aria-label=\"Regional throughput\">\n          <div class=\"co-orbit\" aria-hidden=\"true\">\n            <span class=\"co-orbit-core\"></span>\n            <span class=\"co-orbit-ring co-orbit-r1\"></span>\n            <span class=\"co-orbit-ring co-orbit-r2\"></span>\n            <span class=\"co-orbit-node co-orbit-n1\"></span>\n            <span class=\"co-orbit-node co-orbit-n2\"></span>\n            <span class=\"co-orbit-node co-orbit-n3\"></span>\n          </div>\n          <div class=\"co-photo-caption\">\n            <span class=\"co-photo-kpi\">316,258</span>\n            <span class=\"co-photo-label\">units reconciled today</span>\n          </div>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── TRUST STRIP ────────────────────────────────────────────────────── -->\n    <section class=\"co-trust\" aria-label=\"Trusted by operations teams\">\n      <p class=\"co-trust-copy\">Operations teams at these companies run on Northwind</p>\n      <ul class=\"co-trust-logos\">\n        <li>MERIDIAN</li>\n        <li>PORTWAY</li>\n        <li>ALTIFUND</li>\n        <li>NORDVIK</li>\n        <li>CALDERA</li>\n        <li>BLUEROCK</li>\n      </ul>\n    </section>\n\n    <!-- ── DARK FEATURE BAND ───────────────────────────────────────────────── -->\n    <section id=\"co-product\" class=\"co-band\" aria-labelledby=\"coBandH\">\n      <div class=\"co-band-head\">\n        <p class=\"co-band-eyebrow\">Command</p>\n        <h2 id=\"coBandH\" class=\"co-band-title\">Govern the model, not the spreadsheets</h2>\n        <p class=\"co-band-sub\">One control plane for every metric your operation reports. Lineage, access, and definitions held in one place.</p>\n      </div>\n      <div class=\"co-band-grid\">\n        <article class=\"co-band-card\">\n          <svg class=\"co-line-icon\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><path d=\"M6 40V16M6 24h20V8M6 32h30V20\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><circle cx=\"6\" cy=\"40\" r=\"2.4\" fill=\"currentColor\"/><circle cx=\"26\" cy=\"16\" r=\"2.4\" fill=\"currentColor\"/><circle cx=\"36\" cy=\"20\" r=\"2.4\" fill=\"currentColor\"/></svg>\n          <h3>Metric lineage</h3>\n          <p>Trace any number back to its source rows. Definitions versioned and auditable.</p>\n        </article>\n        <article class=\"co-band-card\">\n          <svg class=\"co-line-icon\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"32\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M16 28l6-8 5 6 5-9\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n          <h3>Anomaly detection</h3>\n          <p>Scouts watch every series and surface the outliers before they reach the floor.</p>\n        </article>\n        <article class=\"co-band-card\">\n          <svg class=\"co-line-icon\" viewBox=\"0 0 48 48\" aria-hidden=\"true\"><circle cx=\"24\" cy=\"24\" r=\"16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\"/><path d=\"M24 14v10l7 4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.6\" stroke-linecap=\"round\"/></svg>\n          <h3>Scheduled digests</h3>\n          <p>Every shift gets the reconciled board, in their inbox, on their clock.</p>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── PRODUCT CARDS (soft stone, 3-up) ────────────────────────────────── -->\n    <section id=\"co-proof\" class=\"co-products\" aria-labelledby=\"coProductsH\">\n      <div class=\"co-products-head\">\n        <p class=\"co-eyebrow\">The platform</p>\n        <h2 id=\"coProductsH\" class=\"co-section-h\">Built for the whole operation</h2>\n      </div>\n      <div class=\"co-product-grid\">\n        <article class=\"co-product-card\">\n          <span class=\"co-product-tag\">Boards</span>\n          <h3>Live operations boards</h3>\n          <p>Throughput, yield, and cost on one surface, refreshed every fifteen minutes.</p>\n          <ul class=\"co-checks\">\n            <li>Unlimited regions and lines</li>\n            <li>Shift-aware time windows</li>\n            <li>Drill-down to the row</li>\n          </ul>\n        </article>\n        <article class=\"co-product-card\">\n          <span class=\"co-product-tag\">Models</span>\n          <h3>Governed metric model</h3>\n          <p>A semantic layer your analysts and your operators both read from.</p>\n          <ul class=\"co-checks\">\n            <li>Versioned definitions</li>\n            <li>Row-level access rules</li>\n            <li>Certified for audit</li>\n          </ul>\n        </article>\n        <article class=\"co-product-card\">\n          <span class=\"co-product-tag\">Agents</span>\n          <h3>Operations agents</h3>\n          <p>Agents that reconcile, summarise, and flag &mdash; grounded on your model.</p>\n          <ul class=\"co-checks\">\n            <li>Reconciler and digest writer</li>\n            <li>Cited, source-linked answers</li>\n            <li>Runs on your schedule</li>\n          </ul>\n        </article>\n      </div>\n    </section>\n\n    <!-- ── EDITORIAL / RESEARCH ────────────────────────────────────────────── -->\n    <section id=\"co-editorial\" class=\"co-editorial\" aria-labelledby=\"coEditorialH\">\n      <div class=\"co-editorial-head\">\n        <div>\n          <p class=\"co-eyebrow\">Research</p>\n          <h2 id=\"coEditorialH\" class=\"co-section-h\">Notes from the operations desk</h2>\n        </div>\n        <div class=\"co-chips\" id=\"coChips\" role=\"group\" aria-label=\"Filter research by topic\"></div>\n      </div>\n      <ul class=\"co-table\" id=\"coTable\"></ul>\n    </section>\n\n    <!-- ── PLANS ───────────────────────────────────────────────────────────── -->\n    <section id=\"co-plans\" class=\"co-plans\" aria-labelledby=\"coPlansH\">\n      <div class=\"co-plans-copy\">\n        <p class=\"co-eyebrow\">Plans</p>\n        <h2 id=\"coPlansH\" class=\"co-section-h\">An operations tier for every scale</h2>\n        <p class=\"co-plans-sub\">Start on a single line and expand per region. No card for the first 30 days.</p>\n        <a class=\"co-btn co-btn-primary\" href=\"#\">Start free trial</a>\n      </div>\n      <div class=\"co-plan-cards\">\n        <article class=\"co-plan\">\n          <span class=\"co-plan-name\">Line</span>\n          <span class=\"co-plan-price\">$1,900<span>/mo</span></span>\n          <ul><li>1 region</li><li>Up to 10 seats</li><li>Weekly digests</li></ul>\n        </article>\n        <article class=\"co-plan co-plan-featured\">\n          <span class=\"co-plan-name\">Operations</span>\n          <span class=\"co-plan-price\">$4,900<span>/mo</span></span>\n          <ul><li>Up to 6 regions</li><li>40 seats included</li><li>Agents + digests</li></ul>\n        </article>\n        <article class=\"co-plan\">\n          <span class=\"co-plan-name\">Command</span>\n          <span class=\"co-plan-price\">Custom</span>\n          <ul><li>Unlimited regions</li><li>SSO &amp; audit</li><li>Dedicated model owner</li></ul>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER (dark newsletter) ─────────────────────────────────────────── -->\n  <footer id=\"co-foot\" class=\"co-foot\">\n    <div class=\"co-news\">\n      <p class=\"co-news-eyebrow\">AI moves fast</p>\n      <h2 class=\"co-news-title\">The operations digest, monthly</h2>\n      <form class=\"co-news-form\" id=\"coNews\">\n        <label class=\"co-news-field\">\n          <span class=\"co-sr\">Email address</span>\n          <input type=\"email\" placeholder=\"you@company.com\" autocomplete=\"email\">\n        </label>\n        <button class=\"co-news-go\" type=\"submit\" aria-label=\"Subscribe\">&rarr;</button>\n      </form>\n      <p class=\"co-news-note\" id=\"coNewsNote\">Sample data — showcase only.</p>\n    </div>\n    <div class=\"co-foot-cols\">\n      <div class=\"co-foot-col\"><h3>Product</h3><a href=\"#\">Boards</a><a href=\"#\">Metric model</a><a href=\"#\">Agents</a><a href=\"#\">Integrations</a></div>\n      <div class=\"co-foot-col\"><h3>Solutions</h3><a href=\"#\">Manufacturing</a><a href=\"#\">Logistics</a><a href=\"#\">Financial ops</a><a href=\"#\">Public sector</a></div>\n      <div class=\"co-foot-col\"><h3>Resources</h3><a href=\"#\">Research</a><a href=\"#\">Docs</a><a href=\"#\">Security</a><a href=\"#\">Changelog</a></div>\n      <div class=\"co-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Newsroom</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"co-legal\">\n      <span>&copy; 2026 Northwind Analytics — a fictional product. <a href=\"#\">Privacy</a> &middot; <a href=\"#\">Terms</a></span>\n      <span>Philippines</span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ NORTHWIND — in Cohere's design language, for showcase.html ═════════════\n   White editorial canvas broken by a deep-green product band, rounded media\n   cards (22px), pill CTAs in near-black, coral taxonomy chips, blue editorial\n   links, and a rule-separated research table. Display type is tight and carved\n   (negative tracking); body settles into restrained 16-24px UI copy. Flat, no\n   heavy shadows — depth from surface alternation and thin borders. */\n\n.own-cohere {\n  --primary: #17171c;\n  --cohere-black: #000000;\n  --ink: #212121;\n  --deep-green: #003c33;\n  --dark-navy: #071829;\n  --canvas: #ffffff;\n  --soft-stone: #eeece7;\n  --pale-green: #edfce9;\n  --pale-blue: #f1f5ff;\n  --hairline: #d9d9dd;\n  --border-light: #e5e7eb;\n  --muted: #93939f;\n  --slate: #75758a;\n  --body-muted: #616161;\n  --action-blue: #1863dc;\n  --focus-blue: #4c6ee6;\n  --coral: #ff7759;\n  --coral-soft: #ffad9b;\n  --on-dark: #ffffff;\n  --error: #b30000;\n\n  --font-display: 'CohereText', 'Space Grotesk', 'Inter', ui-sans-serif, system-ui, sans-serif;\n  --font-ui: 'Unica77 Cohere Web', 'Inter', Arial, ui-sans-serif, system-ui, sans-serif;\n  --font-mono: 'CohereMono', 'Arial', ui-sans-serif, system-ui, sans-serif;\n\n  --r-xs: 4px;\n  --r-sm: 8px;\n  --r-md: 16px;\n  --r-lg: 22px;\n  --r-xl: 30px;\n  --r-pill: 32px;\n\n  --gut: clamp(20px, 5cqi, 64px);\n  --section: clamp(56px, 8cqi, 80px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--font-ui);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  overflow-x: clip;\n}\n.own-cohere *, .own-cohere *::before, .own-cohere *::after { box-sizing: border-box; }\n.own-cohere a { color: inherit; text-decoration: none; }\n.own-cohere button { font: inherit; cursor: pointer; }\n.own-cohere :focus-visible { outline: 3px solid var(--focus-blue); outline-offset: 2px; border-radius: var(--r-xs); }\n.own-cohere .co-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n\n/* ── announcement bar (black, 36px) ───────────────────────────────────────── */\n.own-cohere .co-announce {\n  display: flex; align-items: center; justify-content: center; gap: 12px;\n  min-height: 36px; padding: 8px 44px 8px 16px; position: relative;\n  background: var(--cohere-black); color: var(--on-dark);\n  font-size: 12px; line-height: 1.4;\n}\n.own-cohere .co-announce p { margin: 0; text-align: center; }\n.own-cohere .co-announce a { color: var(--on-dark); text-decoration: underline; text-underline-offset: 2px; }\n.own-cohere .co-announce-x { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); width: 24px; height: 24px; border: 0; background: transparent; color: var(--on-dark); font-size: 18px; line-height: 1; }\n.own-cohere .co-announce[hidden] { display: none; }\n\n/* ── nav ───────────────────────────────────────────────────────────────────── */\n.own-cohere .co-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 24px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(255, 255, 255, .86);\n  border-bottom: 1px solid var(--border-light);\n  backdrop-filter: saturate(180%) blur(12px); -webkit-backdrop-filter: saturate(180%) blur(12px);\n}\n.own-cohere .co-wordmark { font-family: var(--font-display); font-size: 22px; font-weight: 500; letter-spacing: -.4px; color: var(--ink); }\n.own-cohere .co-menu { display: flex; gap: 26px; margin: 0 auto; font-size: 14px; font-weight: 400; }\n.own-cohere .co-menu a { color: var(--ink); padding: 4px 0; border-bottom: 2px solid transparent; }\n.own-cohere .co-menu a:hover { border-bottom-color: var(--ink); }\n.own-cohere .co-nav-right { display: flex; align-items: center; gap: 16px; margin-left: auto; }\n.own-cohere .co-nav-link { font-size: 14px; color: var(--ink); }\n.own-cohere .co-nav-link:hover { text-decoration: underline; text-underline-offset: 3px; }\n.own-cohere .co-burger { display: none; flex-direction: column; gap: 5px; width: 40px; height: 40px; align-items: center; justify-content: center; border: 1px solid var(--border-light); border-radius: var(--r-xs); background: var(--canvas); }\n.own-cohere .co-burger span { display: block; width: 18px; height: 2px; background: var(--ink); }\n\n/* ── buttons ──────────────────────────────────────────────────────────────── */\n.own-cohere .co-btn { display: inline-flex; align-items: center; justify-content: center; height: 48px; padding: 0 26px; border: 0; border-radius: var(--r-pill); font-family: var(--font-ui); font-size: 14px; font-weight: 500; line-height: 1.71; transition: background-color .2s, color .2s; }\n.own-cohere .co-btn-sm { height: 40px; padding: 0 20px; }\n.own-cohere .co-btn-primary { background: var(--primary); color: var(--on-dark); }\n.own-cohere .co-btn-primary:hover { background: #2a2a33; }\n.own-cohere .co-link { display: inline-flex; align-items: center; gap: 8px; font-size: 16px; color: var(--action-blue); }\n.own-cohere .co-link:hover { text-decoration: underline; text-underline-offset: 3px; }\n\n/* ── type helpers ─────────────────────────────────────────────────────────── */\n.own-cohere .co-eyebrow { font-family: var(--font-mono); font-size: 14px; letter-spacing: .28px; text-transform: uppercase; color: var(--slate); margin-bottom: 16px; }\n.own-cohere .co-section-h { font-family: var(--font-ui); font-size: clamp(32px, 4.2cqi, 48px); font-weight: 400; line-height: 1.15; letter-spacing: -.48px; }\n\n/* ── hero ──────────────────────────────────────────────────────────────────── */\n.own-cohere .co-hero { padding: var(--section) var(--gut) clamp(40px, 6cqi, 72px); text-align: center; }\n.own-cohere .co-hero-title { font-family: var(--font-display); font-size: clamp(44px, 8.2cqi, 96px); font-weight: 400; line-height: 1; letter-spacing: -.02em; max-width: 15ch; margin: 0 auto; }\n.own-cohere .co-hero-sub { max-width: 62ch; margin: 24px auto 0; font-size: clamp(16px, 1.3cqi, 18px); line-height: 1.4; color: var(--body-muted); }\n.own-cohere .co-hero-cta { display: flex; align-items: center; justify-content: center; gap: 28px; flex-wrap: wrap; margin-top: 32px; }\n.own-cohere .co-hero-media { display: grid; grid-template-columns: 1.62fr 1fr; gap: 20px; margin-top: clamp(40px, 6cqi, 72px); text-align: left; }\n.own-cohere .co-media-card { border-radius: var(--r-lg); overflow: hidden; }\n\n/* console card */\n.own-cohere .co-media-wide { background: var(--dark-navy); }\n.own-cohere .co-console { color: #e8ecf5; padding: clamp(18px, 2.4cqi, 30px); }\n.own-cohere .co-console-bar { display: flex; align-items: center; gap: 12px; padding-bottom: 16px; border-bottom: 1px solid rgba(255, 255, 255, .12); }\n.own-cohere .co-console-name { font-size: 14px; font-weight: 500; letter-spacing: .2px; }\n.own-cohere .co-chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: var(--r-pill); background: rgba(255, 255, 255, .1); font-size: 12px; color: #cdd5e4; }\n.own-cohere .co-chip-live { margin-left: auto; color: #b9f5d8; }\n.own-cohere .co-chip-live i { width: 6px; height: 6px; border-radius: 50%; background: #4ade80; }\n.own-cohere .co-console-body { padding-top: 18px; display: grid; gap: 18px; }\n.own-cohere .co-prompt { display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-radius: var(--r-md); background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .1); }\n.own-cohere .co-prompt-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--coral); flex: none; }\n.own-cohere .co-prompt-txt { font-size: 14px; color: #eef1f8; }\n.own-cohere .co-console-cols { display: grid; grid-template-columns: 1fr 1.3fr; gap: 18px; }\n.own-cohere .co-console-col { display: grid; gap: 10px; align-content: start; }\n.own-cohere .co-console-h { font-family: var(--font-mono); font-size: 11px; letter-spacing: .8px; text-transform: uppercase; color: #90a0b8; }\n.own-cohere .co-agent { display: flex; align-items: center; gap: 8px; font-size: 13px; color: #dbe2ee; }\n.own-cohere .co-agent-dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }\n.own-cohere .co-a1 { background: var(--coral); }\n.own-cohere .co-a2 { background: #8cc8ff; }\n.own-cohere .co-a3 { background: #ffd27a; }\n.own-cohere .co-console-answer p { margin: 0; font-size: 14px; line-height: 1.5; color: #e7ecf5; }\n.own-cohere .co-badges { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 4px; }\n.own-cohere .co-badge { padding: 4px 10px; border-radius: var(--r-pill); border: 1px solid rgba(255, 255, 255, .2); font-size: 11px; color: #cdd5e4; }\n.own-cohere .co-console-foot { display: flex; gap: 10px; flex-wrap: wrap; }\n\n/* photo card */\n.own-cohere .co-media-photo { position: relative; min-height: 260px; background: linear-gradient(150deg, #0a2b4f 0%, #123a63 45%, #1b5a86 100%); display: flex; flex-direction: column; justify-content: flex-end; }\n.own-cohere .co-orbit { position: absolute; inset: 0; overflow: hidden; }\n.own-cohere .co-orbit-core { position: absolute; left: 50%; top: 42%; transform: translate(-50%, -50%); width: 42%; aspect-ratio: 1; border-radius: 50%; background: radial-gradient(circle at 40% 35%, #ff8f6b, #d9432c 70%); box-shadow: 0 0 60px rgba(255, 119, 89, .5); }\n.own-cohere .co-orbit-ring { position: absolute; left: 50%; top: 42%; transform: translate(-50%, -50%); border-radius: 50%; border: 1.5px solid rgba(255, 255, 255, .3); }\n.own-cohere .co-orbit-r1 { width: 66%; aspect-ratio: 1; }\n.own-cohere .co-orbit-r2 { width: 90%; aspect-ratio: 1; border-color: rgba(255, 255, 255, .16); }\n.own-cohere .co-orbit-node { position: absolute; width: 12px; height: 12px; border-radius: 50%; background: #fff; box-shadow: 0 0 14px rgba(255, 255, 255, .8); }\n.own-cohere .co-orbit-n1 { left: 20%; top: 26%; }\n.own-cohere .co-orbit-n2 { right: 18%; top: 50%; }\n.own-cohere .co-orbit-n3 { left: 34%; bottom: 22%; }\n.own-cohere .co-photo-caption { position: relative; z-index: 2; padding: clamp(18px, 2.4cqi, 28px); background: linear-gradient(0deg, rgba(7, 24, 41, .92), rgba(7, 24, 41, 0)); }\n.own-cohere .co-photo-kpi { display: block; font-family: var(--font-display); font-size: clamp(30px, 3.6cqi, 44px); font-weight: 400; line-height: 1; letter-spacing: -1px; color: #fff; }\n.own-cohere .co-photo-label { display: block; margin-top: 4px; font-size: 13px; color: #cdd8e6; }\n\n/* ── trust strip ──────────────────────────────────────────────────────────── */\n.own-cohere .co-trust { padding: clamp(48px, 6cqi, 72px) var(--gut); text-align: center; }\n.own-cohere .co-trust-copy { font-size: 14px; color: var(--slate); margin-bottom: 32px; }\n.own-cohere .co-trust-logos { list-style: none; display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: clamp(28px, 5cqi, 72px); }\n.own-cohere .co-trust-logos li { font-family: var(--font-display); font-size: clamp(16px, 1.8cqi, 20px); font-weight: 500; letter-spacing: .12em; color: #1b1b22; opacity: .82; }\n\n/* ── dark feature band ────────────────────────────────────────────────────── */\n.own-cohere .co-band { margin: 0 var(--gut); padding: var(--section) clamp(24px, 4cqi, 64px); border-radius: var(--r-lg); background: var(--deep-green); color: var(--on-dark); }\n.own-cohere .co-band-head { max-width: 720px; }\n.own-cohere .co-band-eyebrow { font-family: var(--font-mono); font-size: 14px; letter-spacing: .28px; text-transform: uppercase; color: #9fd8c6; margin-bottom: 16px; }\n.own-cohere .co-band-title { font-family: var(--font-display); font-size: clamp(34px, 5cqi, 60px); font-weight: 400; line-height: 1; letter-spacing: -1.2px; }\n.own-cohere .co-band-sub { margin-top: 18px; font-size: clamp(16px, 1.3cqi, 18px); line-height: 1.4; color: #cfe6df; max-width: 52ch; }\n.own-cohere .co-band-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: clamp(36px, 5cqi, 60px); }\n.own-cohere .co-band-card { padding: 24px; border-radius: var(--r-md); background: rgba(255, 255, 255, .06); border: 1px solid rgba(255, 255, 255, .14); }\n.own-cohere .co-line-icon { width: 40px; height: 40px; color: #b9f5d8; margin-bottom: 16px; }\n.own-cohere .co-band-card h3 { font-size: 20px; font-weight: 500; letter-spacing: -.1px; }\n.own-cohere .co-band-card p { margin-top: 8px; font-size: 15px; line-height: 1.5; color: #cfe6df; }\n\n/* ── product cards (soft stone) ───────────────────────────────────────────── */\n.own-cohere .co-products { padding: var(--section) var(--gut); }\n.own-cohere .co-products-head { text-align: center; max-width: 720px; margin: 0 auto clamp(32px, 5cqi, 56px); }\n.own-cohere .co-product-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }\n.own-cohere .co-product-card { padding: 32px; border-radius: var(--r-sm); background: var(--soft-stone); }\n.own-cohere .co-product-tag { display: inline-block; font-family: var(--font-mono); font-size: 12px; letter-spacing: .28px; text-transform: uppercase; color: var(--slate); margin-bottom: 14px; }\n.own-cohere .co-product-card h3 { font-size: 24px; font-weight: 400; line-height: 1.3; letter-spacing: -.1px; }\n.own-cohere .co-product-card p { margin-top: 10px; font-size: 16px; line-height: 1.5; color: var(--body-muted); }\n.own-cohere .co-checks { list-style: none; margin-top: 20px; display: grid; gap: 10px; }\n.own-cohere .co-checks li { position: relative; padding-left: 24px; font-size: 14px; color: var(--ink); }\n.own-cohere .co-checks li::before { content: ''; position: absolute; left: 0; top: 6px; width: 12px; height: 7px; border-left: 2px solid var(--deep-green); border-bottom: 2px solid var(--deep-green); transform: rotate(-45deg); }\n\n/* ── editorial / research ──────────────────────────────────────────────────── */\n.own-cohere .co-editorial { padding: var(--section) var(--gut); background: var(--pale-blue); }\n.own-cohere .co-editorial-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; flex-wrap: wrap; margin-bottom: 32px; }\n.own-cohere .co-chips { display: flex; flex-wrap: wrap; gap: 8px; }\n.own-cohere .co-chip-topic { padding: 8px 14px; border-radius: var(--r-sm); border: 1px solid var(--coral-soft); background: transparent; font-size: 14px; color: var(--coral); transition: background-color .2s, color .2s; }\n.own-cohere .co-chip-topic:hover { background: rgba(255, 119, 89, .1); }\n.own-cohere .co-chip-topic[aria-pressed=\"true\"] { background: var(--coral); color: var(--ink); border-color: var(--coral); }\n.own-cohere .co-table { list-style: none; border-top: 1px solid var(--hairline); }\n.own-cohere .co-row { display: grid; grid-template-columns: 1fr auto auto; align-items: center; gap: 24px; padding: 22px 0; border-bottom: 1px solid var(--hairline); }\n.own-cohere .co-row-title { font-size: clamp(18px, 1.6cqi, 22px); line-height: 1.3; color: var(--ink); }\n.own-cohere .co-row-title a:hover { color: var(--action-blue); }\n.own-cohere .co-row-topic { padding: 6px 14px; border-radius: var(--r-xl); border: 1px solid var(--slate); font-family: var(--font-mono); font-size: 12px; letter-spacing: .2px; color: var(--slate); white-space: nowrap; }\n.own-cohere .co-row-date { font-family: var(--font-mono); font-size: 13px; color: var(--muted); white-space: nowrap; min-width: 92px; text-align: right; }\n\n/* ── plans ─────────────────────────────────────────────────────────────────── */\n.own-cohere .co-plans { display: grid; grid-template-columns: .8fr 1.6fr; gap: clamp(28px, 4cqi, 56px); padding: var(--section) var(--gut); align-items: start; }\n.own-cohere .co-plans-sub { margin: 18px 0 26px; font-size: 16px; line-height: 1.5; color: var(--body-muted); max-width: 40ch; }\n.own-cohere .co-plan-cards { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; }\n.own-cohere .co-plan { display: grid; gap: 10px; align-content: start; padding: 28px; border: 1px solid var(--border-light); border-radius: var(--r-md); background: var(--canvas); }\n.own-cohere .co-plan-name { font-family: var(--font-mono); font-size: 13px; letter-spacing: .28px; text-transform: uppercase; color: var(--slate); }\n.own-cohere .co-plan-price { font-family: var(--font-display); font-size: clamp(28px, 3cqi, 38px); font-weight: 400; letter-spacing: -.6px; }\n.own-cohere .co-plan-price span { font-family: var(--font-ui); font-size: 14px; color: var(--slate); letter-spacing: 0; }\n.own-cohere .co-plan ul { list-style: none; display: grid; gap: 8px; margin-top: 6px; padding-top: 14px; border-top: 1px solid var(--border-light); font-size: 14px; color: var(--body-muted); }\n.own-cohere .co-plan-featured { background: var(--pale-green); border-color: #c9e6d5; }\n\n/* ── footer ─────────────────────────────────────────────────────────────────── */\n.own-cohere .co-foot { background: var(--primary); color: var(--on-dark); padding: clamp(48px, 6cqi, 80px) var(--gut) 32px; }\n.own-cohere .co-news { max-width: 560px; padding-bottom: 40px; border-bottom: 1px solid rgba(255, 255, 255, .14); }\n.own-cohere .co-news-eyebrow { font-family: var(--font-mono); font-size: 14px; letter-spacing: .28px; text-transform: uppercase; color: var(--coral); }\n.own-cohere .co-news-title { margin-top: 12px; font-family: var(--font-display); font-size: clamp(28px, 3.6cqi, 44px); font-weight: 400; line-height: 1.05; letter-spacing: -.6px; }\n.own-cohere .co-news-form { display: flex; gap: 10px; margin-top: 24px; max-width: 440px; }\n.own-cohere .co-news-field { flex: 1; }\n.own-cohere .co-news-field input { width: 100%; height: 48px; padding: 0 16px; border: 1px solid rgba(255, 255, 255, .28); border-radius: var(--r-xs); background: rgba(255, 255, 255, .06); color: #fff; font: inherit; font-size: 15px; }\n.own-cohere .co-news-field input::placeholder { color: rgba(255, 255, 255, .55); }\n.own-cohere .co-news-field input:focus { outline: none; border-color: var(--focus-blue); box-shadow: 0 0 0 3px rgba(76, 110, 230, .4); }\n.own-cohere .co-news-go { width: 48px; height: 48px; flex: none; border: 0; border-radius: var(--r-xs); background: var(--coral); color: var(--primary); font-size: 20px; }\n.own-cohere .co-news-go:hover { background: var(--coral-soft); }\n.own-cohere .co-news-note { margin-top: 14px; font-size: 12px; color: rgba(255, 255, 255, .6); }\n.own-cohere .co-foot-cols { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; padding: 40px 0; }\n.own-cohere .co-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-cohere .co-foot-col h3 { font-size: 13px; font-weight: 500; letter-spacing: .2px; color: #fff; margin-bottom: 4px; }\n.own-cohere .co-foot-col a { font-size: 14px; color: rgba(255, 255, 255, .66); }\n.own-cohere .co-foot-col a:hover { color: #fff; }\n.own-cohere .co-legal { display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap; padding-top: 22px; border-top: 1px solid rgba(255, 255, 255, .14); font-size: 12px; color: rgba(255, 255, 255, .62); }\n.own-cohere .co-legal a { color: rgba(255, 255, 255, .78); text-decoration: underline; text-underline-offset: 2px; }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-cohere .co-menu { display: none; }\n  .own-cohere .co-burger { display: flex; }\n  .own-cohere .co-hero-media { grid-template-columns: 1fr; }\n  .own-cohere .co-band-grid { grid-template-columns: 1fr; }\n  .own-cohere .co-product-grid { grid-template-columns: 1fr; }\n  .own-cohere .co-plans { grid-template-columns: 1fr; }\n  .own-cohere .co-plan-cards { grid-template-columns: 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-cohere .co-nav { top: 66px; height: 58px; gap: 12px; }\n  .own-cohere .co-console-cols { grid-template-columns: 1fr; }\n  .own-cohere .co-row { grid-template-columns: 1fr; gap: 10px; }\n  .own-cohere .co-row-date { text-align: left; }\n  .own-cohere .co-foot-cols { grid-template-columns: repeat(2, 1fr); }\n  .own-cohere .co-hero-title { letter-spacing: -.01em; }\n}\n@container frame (max-width: 430px) {\n  .own-cohere .co-hero-cta { flex-direction: column; gap: 16px; }\n  .own-cohere .co-foot-cols { grid-template-columns: 1fr; }\n  .own-cohere .co-announce { font-size: 11px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-cohere *, .own-cohere *::before, .own-cohere *::after { transition-duration: .001ms !important; animation-duration: .001ms !important; }\n}\n"};
/* ══ NORTHWIND — in Cohere's design language, for showcase.html ═════════════
   Registers window.OWN_LAYOUTS['cohere'].init(root). Renders the research table
   and topic chips, wires the announcement dismiss and the newsletter note, and
   returns a cleanup that detaches every listener. Motion is limited to what the
   design language calls for (none beyond focus/hover), so this is mostly static. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var NOTES = [
    { title: 'Reconciling 14 production lines without a nightly batch', topic: 'Engineering', date: 'Oct 2026' },
    { title: 'Why operations teams should own their metric definitions', topic: 'Governance', date: 'Sep 2026' },
    { title: 'Anomaly scouts: catching the drift before the shift does', topic: 'Research', date: 'Sep 2026' },
    { title: 'A semantic layer that operators actually read', topic: 'Product', date: 'Aug 2026' },
    { title: 'Lineage as a trust signal in regulated manufacturing', topic: 'Governance', date: 'Aug 2026' }
  ];
  var TOPICS = ['All', 'Engineering', 'Governance', 'Research', 'Product'];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['cohere'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $(s) { return root.querySelector(s); }

      /* ── announcement dismiss ──────────────────────────────────────────── */
      var announce = $('#coAnnounce');
      on($('#coAnnounceX'), 'click', function () { if (announce) announce.setAttribute('hidden', ''); });

      /* ── research table + topic chips ───────────────────────────────────── */
      var table = $('#coTable');
      var chips = $('#coChips');
      var active = 'All';

      function rowHTML(n) {
        return '<li class="co-row">'
          + '<span class="co-row-title"><a href="#">' + esc(n.title) + '</a></span>'
          + '<span class="co-row-topic">' + esc(n.topic) + '</span>'
          + '<span class="co-row-date">' + esc(n.date) + '</span>'
          + '</li>';
      }
      function render() {
        if (!table) return;
        var list = NOTES.filter(function (n) { return active === 'All' || n.topic === active; });
        table.innerHTML = list.length ? list.map(rowHTML).join('')
          : '<li class="co-row"><span class="co-row-title">No notes in this topic yet.</span></li>';
      }
      if (chips) {
        chips.innerHTML = TOPICS.map(function (t) {
          return '<button type="button" role="button" class="co-chip-topic" data-topic="' + esc(t) + '" aria-pressed="' + (t === active) + '">' + esc(t) + '</button>';
        }).join('');
      }
      on(chips, 'click', function (e) {
        var b = e.target.closest('[data-topic]');
        if (!b) return;
        active = b.dataset.topic;
        Array.prototype.forEach.call(chips.children, function (c) {
          c.setAttribute('aria-pressed', String(c.dataset.topic === active));
        });
        render();
      });
      render();

      /* ── newsletter (sample form) ───────────────────────────────────────── */
      var news = $('#coNews');
      var note = $('#coNewsNote');
      on(news, 'submit', function (e) {
        e.preventDefault();
        if (note) note.textContent = 'Thanks — this is sample data, nothing was sent.';
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
